// src/mesh/script.js
var script = {
  running: false,
  visible: false,
  changed() {
    localStorage.script = $("script-editor").value;
  },
  error(e) {
    api2.modal.dialog({
      title: "script error",
      body: [h2.div({ id: "script-error", _: e.message || e.toString() })]
    });
  },
  hide() {
    $("script").classList.add("hide");
    api2.prefs.save(api2.prefs.map.space.script = script.visible = false);
  },
  show() {
    $("script").classList.remove("hide");
    $("script-editor").value = localStorage.script ?? "";
    api2.prefs.save(api2.prefs.map.space.script = script.visible = true);
  },
  toggle() {
    if (script.visible) {
      script.hide();
    } else {
      script.show();
    }
  },
  execute() {
    let cmd = localStorage.script || `console.log('no script')`;
    if (cmd) {
      if (script.running) {
        return script.error("script running");
      }
      cmd = [
        "(async () => {",
        cmd,
        "})()",
        ".catch(error => {",
        "api.script.error(error)",
        "})",
        ".finally(() => {",
        "api.script.running = false;",
        "});"
      ].join("\n");
      try {
        eval(`{ 
 ${cmd} 
 }`);
      } catch (e) {
        script.error(e);
      }
    }
  }
};

