      let onclick = (ev2) => {
        let tempval2 = parseFloat($("tempval").value);
        api2.modal.hide(modal.info.cancelled);
        if (modal.info.cancelled) {
          return;
        }
        set(tempval2, value);
        defer_selection();
      };
